//! Static protocol IDs and state properties generated by the official 26.2 data
//! report tool at development time. Compressed data is embedded; no JVM at runtime.
use super::{models::Properties, PROTOCOL, VERSION};
use anyhow::{ensure, Context, Result};
use flate2::read::GzDecoder;
use serde::Deserialize;
use sha1::{Digest, Sha1};
use std::{
    collections::BTreeMap,
    io::Read,
    sync::{Arc, OnceLock},
};
#[derive(Debug)]
pub struct BlockState {
    pub block: Arc<str>,
    pub properties: Properties,
    pub is_default: bool,
}
#[derive(Debug)]
pub struct Builtins {
    registries: BTreeMap<String, Vec<Arc<str>>>,
    pub block_states: Vec<BlockState>,
    defaults: BTreeMap<Arc<str>, u32>,
}
#[derive(Deserialize)]
struct Reference {
    minecraft: String,
    protocol: i32,
    sha1: BTreeMap<String, String>,
}
#[derive(Deserialize)]
struct Registry {
    entries: BTreeMap<String, RegistryEntry>,
}
#[derive(Deserialize)]
struct RegistryEntry {
    protocol_id: usize,
}
#[derive(Deserialize)]
struct Block {
    states: Vec<RawState>,
}
#[derive(Deserialize)]
struct RawState {
    id: usize,
    #[serde(default)]
    properties: Properties,
    #[serde(default)]
    default: bool,
}
fn inflate(bytes: &[u8], hash: &str) -> Result<Vec<u8>> {
    let mut data = Vec::new();
    GzDecoder::new(bytes)
        .take(16 * 1024 * 1024 + 1)
        .read_to_end(&mut data)?;
    ensure!(data.len() <= 16 * 1024 * 1024, "Reference report too large");
    ensure!(
        format!("{:x}", Sha1::digest(&data)) == hash,
        "Reference report SHA-1 mismatch"
    );
    Ok(data)
}
impl Builtins {
    fn load() -> Result<Self> {
        let reference: Reference =
            serde_json::from_str(include_str!("../../data/26.2/reference.json"))?;
        ensure!(
            reference.minecraft == VERSION && reference.protocol == PROTOCOL,
            "Wrong builtin reference version"
        );
        let registry_bytes = inflate(
            include_bytes!("../../data/26.2/registries.json.gz"),
            &reference.sha1["registries.json"],
        )?;
        let raw: BTreeMap<String, Registry> = serde_json::from_slice(&registry_bytes)?;
        let mut registries = BTreeMap::new();
        for (kind, registry) in raw {
            let mut ids = vec![None; registry.entries.len()];
            for (name, entry) in registry.entries {
                let slot = ids
                    .get_mut(entry.protocol_id)
                    .context("Non-contiguous registry IDs")?;
                ensure!(slot.is_none(), "Duplicate protocol ID");
                *slot = Some(Arc::from(name));
            }
            registries.insert(
                kind,
                ids.into_iter()
                    .map(|id| id.context("Missing protocol ID"))
                    .collect::<Result<Vec<_>>>()?,
            );
        }
        let block_bytes = inflate(
            include_bytes!("../../data/26.2/blocks.json.gz"),
            &reference.sha1["blocks.json"],
        )?;
        let blocks: BTreeMap<String, Block> = serde_json::from_slice(&block_bytes)?;
        let count = blocks.values().map(|b| b.states.len()).sum::<usize>();
        let mut states: Vec<Option<BlockState>> = (0..count).map(|_| None).collect();
        let mut defaults = BTreeMap::new();
        for (name, block) in blocks {
            let name: Arc<str> = Arc::from(name);
            for state in block.states {
                let slot = states
                    .get_mut(state.id)
                    .context("Block state ID outside report range")?;
                ensure!(slot.is_none(), "Duplicate block state ID");
                if state.default {
                    ensure!(
                        defaults.insert(name.clone(), state.id as u32).is_none(),
                        "Multiple block defaults"
                    );
                }
                *slot = Some(BlockState {
                    block: name.clone(),
                    properties: state.properties,
                    is_default: state.default,
                });
            }
        }
        let block_states = states
            .into_iter()
            .map(|s| s.context("Missing block state ID"))
            .collect::<Result<Vec<_>>>()?;
        Ok(Self {
            registries,
            block_states,
            defaults,
        })
    }
    pub fn name(&self, registry: &str, id: u32) -> Option<&str> {
        self.registries
            .get(registry)?
            .get(id as usize)
            .map(|s| s.as_ref())
    }
    pub fn state(&self, id: u32) -> Option<&BlockState> {
        self.block_states.get(id as usize)
    }
    pub fn default_state(&self, block: &str) -> Option<u32> {
        self.defaults.get(block).copied()
    }
    pub fn registry_count(&self) -> usize {
        self.registries.len()
    }
}
pub fn get() -> Result<&'static Builtins> {
    static DATA: OnceLock<Result<Builtins, String>> = OnceLock::new();
    DATA.get_or_init(|| Builtins::load().map_err(|e| format!("{e:#}")))
        .as_ref()
        .map_err(|e| anyhow::anyhow!(e.clone()))
}
#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn generated_protocol_776_ids_and_properties_are_complete() {
        let data = get().unwrap();
        assert_eq!(data.registry_count(), 95);
        assert_eq!(data.block_states.len(), 32366);
        assert_eq!(
            data.name("minecraft:entity_type", 32),
            Some("minecraft:creeper")
        );
        assert_eq!(
            data.name("minecraft:entity_type", 156),
            Some("minecraft:player")
        );
        assert_eq!(data.state(0).unwrap().block.as_ref(), "minecraft:air");
        let stairs = data
            .state(data.default_state("minecraft:oak_stairs").unwrap())
            .unwrap();
        assert_eq!(stairs.properties["facing"], "north");
        assert_eq!(stairs.properties["waterlogged"], "false");
        assert!(data.state(32366).is_none());
        assert!(std::ptr::eq(get().unwrap(), data));
    }
}
